 COALESCE(T.BK_SALES_ADJ_NUMBER_INT, -999) AS BK_SALES_ADJ_NUMBER_INT,
 /*NO COL NO NULL BUT NO DEFAULT VALUE*/
 'UNKNOWN'AS DV_DEAL_ID,
