 COALESCE(T.FISCAL_WEEK_NAME , 'UNKNOWN') AS FISCAL_WEEK_NAME,
 COALESCE(T.FISCAL_YEAR_MONTH_INT ,'-999') AS FISCAL_YEAR_MONTH_INT,
