 COALESCE(T.SALES_MOTION_CD, 'UNKNOWN' ) AS SALES_MOTION_CD,
 COALESCE(T.SUMMARY_QUOTE_FLG, 'N' ) AS SUMMARY_QUOTE_FLG,
 T.ADJUSTMENT_DESCR_KEY,
 COALESCE(T.DV_RECURRING_OFFER_CD, 'UNKNOWN' ) AS DV_RECURRING_OFFER_CD,
 T.SK_SALES_MOTION_ATTRIB_KEY,
 T.WIPS_ORIGINATOR_ID_INT,
 /*Added as part of SFP Q4FY21 Rel*/
 T.MAGIC_KEY_ID,
